package com.tenora365.service;import com.fasterxml.jackson.databind.ObjectMapper;import com.tenora365.entity.AuditLog;import com.tenora365.repository.AuditLogRepository;import com.tenora365.tenant.TenantContext;import jakarta.servlet.http.HttpServletRequest;import org.springframework.stereotype.Service;import java.util.*;
@Service public class AuditService{final AuditLogRepository repo;final ObjectMapper mapper=new ObjectMapper();AuditService(AuditLogRepository r){repo=r;}public void log(Long user,String action,String type,String id,Object details,HttpServletRequest req){AuditLog a=new AuditLog();a.setSchoolId(TenantContext.get());a.setUserId(user);a.setAction(action);a.setEntityType(type);a.setEntityId(id);a.setIpAddress(req==null?null:req.getRemoteAddr());try{a.setDetails(details==null?null:mapper.writeValueAsString(details));}catch(Exception e){a.setDetails(String.valueOf(details));}repo.save(a);}}
